      return DateTimeRange(
        start: DateTime.fromMillisecondsSinceEpoch(
          arguments['initialStartDate'] as int,
        ),
        end: DateTime.fromMillisecondsSinceEpoch(
          arguments['initialEndDate'] as int,
        ),
      );
    }

    return null;
  }

